(function(){
'use strict';
const C=window.THCore,X=window.THExperience,M=window.THExperienceMarkup;if(!C||!X||!M||!window.TECH_HORIZON)return;
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],E=C.escape;
const stored=C.storage.get('th-draft',null),D=C.storage.get('th-preview',false)&&stored&&C.validate(stored).length===0?stored:window.TECH_HORIZON,base=document.body.dataset.base||'',page=document.body.dataset.page||'',routes=new Set(window.TH_STATIC_ROUTES||[]);
const articleUrl=a=>routes.has(a.id)?base+'bai-viet/'+a.id+'.html':base+'doc-bai.html?id='+encodeURIComponent(a.id);
const systemReduced=window.matchMedia('(prefers-reduced-motion: reduce)'),finePointer=window.matchMedia('(hover:hover) and (pointer:fine)');let paused=false;
function motionDisabled(){return paused||systemReduced.matches||document.documentElement.dataset.motion==='reduce';}
function patchLinks(root=document){$$('[data-experience-article]',root).forEach(a=>{const item=D.articles.find(x=>x.id===a.dataset.experienceArticle);if(item)a.href=articleUrl(item);});}
if(page==='home'){
 if(C.storage.get('th-preview',false)&&D!==window.TECH_HORIZON){const hero=$('.horizon-hero');if(hero){const holder=document.createElement('div');holder.innerHTML=M.hero(D,C);hero.replaceWith(holder.firstElementChild);}for(const[selector,markup]of [['.discovery-section',M.discovery(D,C,X)],['.micro-lab-band',M.lab(D,C,X)]]){const old=$(selector);if(old){const holder=document.createElement('div');holder.innerHTML=markup;if(holder.firstElementChild)old.replaceWith(holder.firstElementChild);else old.remove();}}}
 $('[data-exp-description]')?.replaceChildren(document.createTextNode(D.config.description));$('[data-exp-tagline]')?.replaceChildren(document.createTextNode(D.config.tagline));
 const scene=$('#horizon-visual'),motion=$('#experience-motion');
 function updateMotion(){document.documentElement.dataset.experiencePaused=String(motionDisabled());if(motion){motion.setAttribute('aria-pressed',String(motionDisabled()));motion.disabled=systemReduced.matches||document.documentElement.dataset.motion==='reduce';motion.title=motion.disabled?'Đang giảm chuyển động theo tùy chọn thiết bị hoặc website.':'Bật hoặc tắt chuyển động trang chủ';}if(motionDisabled()&&scene){scene.style.setProperty('--scene-x','0px');scene.style.setProperty('--scene-y','0px');}}
 motion?.addEventListener('click',()=>{paused=!paused;updateMotion();});systemReduced.addEventListener?.('change',updateMotion);updateMotion();
 let frame=0;scene?.addEventListener('pointermove',e=>{if(motionDisabled()||!finePointer.matches)return;const rect=scene.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width-.5,y=(e.clientY-rect.top)/rect.height-.5;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{scene.style.setProperty('--scene-x',Math.max(-9,Math.min(9,x*15))+'px');scene.style.setProperty('--scene-y',Math.max(-6,Math.min(6,y*10))+'px');});});scene?.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);scene.style.setProperty('--scene-x','0px');scene.style.setProperty('--scene-y','0px');});
 let interest='all';const result=$('#discovery-results');
 function renderDiscovery(){if(!result)return;try{const items=X.recommendations(D,{category:interest,goal:$('#discovery-goal').value,minutes:$('#discovery-time').value});result.innerHTML=items.length?items.map(a=>M.recommendation(a,D,C)).join(''):'<div class="discovery-empty"><strong>Chưa có cẩm nang vừa mốc thời gian này.</strong><p>Thử chọn 5 hoặc 10 phút để có thêm một góc nhìn.</p><a href="'+base+'tat-ca.html">Xem tất cả cẩm nang ↗</a></div>';$('#discovery-status').textContent=items.length+' gợi ý theo chủ đề và thời gian bạn chọn.';$$('[data-interest]').forEach(b=>{const active=b.dataset.interest===interest;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});patchLinks(result);}catch(err){$('#discovery-status').textContent=err.message;}}
 $$('[data-interest]').forEach(button=>button.addEventListener('click',()=>{interest=button.dataset.interest;renderDiscovery();}));for(const id of ['discovery-goal','discovery-time'])$('#'+id)?.addEventListener('change',renderDiscovery);
 $('#discovery-surprise')?.addEventListener('click',()=>{const candidates=D.articles.filter(a=>(interest==='all'||a.category===interest)&&a.minutes<=Number($('#discovery-time').value));if(!candidates.length){$('#discovery-status').textContent='Thử tăng thời gian để có một bài phù hợp.';return;}let n;try{n=crypto.getRandomValues(new Uint32Array(1))[0];}catch{n=Math.floor(Math.random()*0x100000000);}const a=X.pick(candidates,n);result.innerHTML=M.recommendation(a,D,C);patchLinks(result);$('#discovery-status').textContent='Một bài bất ngờ trong chủ đề đã chọn · '+a.minutes+' phút đọc.';const heading=$('h3 a',result);if(heading)heading.focus();});renderDiscovery();
 const questions=X.labs(D),answers=new Map();let activeQuestion=0;
 if(questions.length&&$('#micro-question')){
  $('#micro-progress').max=questions.length;$('#micro-progress-label').textContent='0 / '+questions.length+' góc nhìn đã mở';
  function feedback(q,index){const result=X.answer(questions,q.id,index),el=$('#micro-feedback');el.hidden=false;el.innerHTML='<strong>'+(result.correct?'Đúng hướng rồi.':'Cùng mở thêm một góc nhìn.')+'</strong><p>'+E(result.explanation)+'</p><a data-experience-article="'+q.article+'" href="'+E(articleUrl(D.articles.find(a=>a.id===q.article)))+'">Đọc cẩm nang và nguồn tham khảo ↗</a>';$$('[data-micro-answer]').forEach(button=>{const i=Number(button.dataset.microAnswer);button.disabled=true;button.setAttribute('aria-pressed',String(i===index));button.classList.toggle('is-correct',i===q.correct);button.classList.toggle('was-chosen',i===index);});$('#micro-progress').value=answers.size;$('#micro-progress-label').textContent=answers.size+' / '+questions.length+' góc nhìn đã mở';}
  function showQuestion(focus=false){const q=questions[activeQuestion];$('#micro-topic').textContent=q.topic;$('#micro-position').textContent=String(activeQuestion+1).padStart(2,'0')+' / '+String(questions.length).padStart(2,'0');$('#micro-question').textContent=q.question;$('#micro-answers').innerHTML=q.answers.map((text,i)=>'<button data-micro-answer="'+i+'" aria-pressed="false"><span>'+String.fromCharCode(65+i)+'</span>'+E(text)+'<i aria-hidden="true">↗</i></button>').join('');$('#micro-feedback').hidden=true;$('#micro-feedback').textContent='';$('#micro-next').textContent=activeQuestion===questions.length-1?'Xem lại từ đầu ↻':'Câu tiếp theo →';if(answers.has(q.id))feedback(q,answers.get(q.id));if(focus)$('#micro-question').focus();}
  $('#micro-answers').addEventListener('click',e=>{const button=e.target.closest('[data-micro-answer]');if(!button)return;const q=questions[activeQuestion],index=Number(button.dataset.microAnswer);if(answers.has(q.id))return;answers.set(q.id,index);feedback(q,index);});$('#micro-next').addEventListener('click',()=>{activeQuestion=(activeQuestion+1)%questions.length;showQuestion(true);});showQuestion();
 }
}
patchLinks();
const pageFile=location.pathname.split('/').pop()||'index.html';$$('.desktop-nav a,.mobile-menu a').forEach(a=>{const href=a.getAttribute('href');if(href&&!href.includes('#')&&href.split('/').pop()===pageFile)a.setAttribute('aria-current','page');});
if('IntersectionObserver'in window&&!motionDisabled()){
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('experience-entered');observer.unobserve(entry.target);}});},{threshold:.1});$$('.spotlight-card,.category-tile,.article-card,.journey-card,.studio-teaser,.glossary-mini-grid a,.command-panel').forEach((el,i)=>{el.style.setProperty('--enter-delay',(i%3)*65+'ms');observer.observe(el);});
}
})();
